/// Стих KJV → (глава, стих) синодальной нумерации
(int, int) toSynodal(String book, int c, int v) {
  for (final r in _k2s[book]?[c] ?? const <List<int>>[]) {
    if (v >= r[0] && v <= r[1]) return (c + r[2], v + r[3]);
  }
  return (c, v);
}

/// Какие главы KJV нужны, чтобы собрать синодальную главу c (обычно одна; на стыках псалмов — две)
List<int> westernChaptersFor(String book, int c) {
  final runs = _k2s[book];
  if (runs == null) return [c];
  final out = <int>{};
  runs.forEach((kc, list) {
    if (list.any((r) => kc + r[2] == c)) out.add(kc);
  });
  final n = (_western[book]?.length ?? 0) >= c ? _western[book]![c - 1] : 0;
  for (var v = 1; v <= n; v++) {
    if (toSynodal(book, c, v).$1 == c) {
      out.add(c);
      break;
    }
  }
  return out.toList()..sort();
}

/// Глава KJV → стихи и заголовки синодальной главы target (что ушло в соседнюю главу — пропускается).
/// title — надписание псалма: в синодальной нумерации это стих 1 (в западной — заголовок над стихом 1)
void placeSynodal(String book, int kc, List<String> verses, Map<int, String> heads, int target, List<String> intoV, Map<int, String> intoH, [String title = '']) {
  final first = toSynodal(book, kc, 1);
  if (title.isNotEmpty && book == 'Ps' && first.$1 == target && first.$2 == 2 && (intoV.isEmpty || intoV[0].isEmpty)) {
    if (intoV.isEmpty) intoV.add('');
    intoV[0] = title;
  }
  for (var i = 0; i < verses.length; i++) {
    final text = verses[i];
    if (text.isEmpty) continue;
    final (c, v) = toSynodal(book, kc, i + 1);
    if (c != target) continue;
    while (intoV.length < v) {
      intoV.add('');
    }
    intoV[v - 1] = intoV[v - 1].isEmpty ? text : '${intoV[v - 1]} $text';
    final h = heads[i + 1];
    if (h != null && !intoH.containsKey(v)) intoH[v] = h;
  }
}

/// Число стихов в синодальных главах книги (нет в таблице — по западному счёту)
List<int> synodalVerses(String book) => _syn[book] ?? _western[book] ?? const [];
